def create_showtime_seats(apps, schema_editor):
    Showtime = apps.get_model('venues', 'Showtime')
    ShowtimeSeat = apps.get_model('venues', 'ShowtimeSeat')

    for showtime in Showtime.objects.select_related('room').all():
        if ShowtimeSeat.objects.filter(showtime=showtime).exists():
            continue
        room = showtime.room
        if not room:
            continue

        total_capacity = room.capacity
        rows = room.rows
        seats_per_row = room.seats_per_row

        seats = []
        created = 0
        for row_index in range(rows):
            if row_index < 26:
                row_label = chr(ord('A') + row_index)
            else:
                row_label = f'R{row_index + 1}'
            for seat_index in range(1, seats_per_row + 1):
                if created >= total_capacity:
                    break
                seat_number = f'{row_label}{seat_index}'
                seats.append(ShowtimeSeat(
                    id=uuid.uuid4(),
                    showtime=showtime,
                    seat_number=seat_number,
                    row_label=row_label,
                    row_index=row_index,
                    seat_index=seat_index,
                    is_reserved=False,
                ))
                created += 1
            if created >= total_capacity:
                break

        if seats:
            ShowtimeSeat.objects.bulk_create(seats)


